-- 九霄问道 V0.11.2 FINAL：五品自动机缘V3
-- 基线：V0.11.1 / 68表57函数。废弃脚本202607240019_auto_opportunity_v2.sql严禁执行。
begin;
create extension if not exists pgcrypto;
create table if not exists public.opportunity_v3_settings(
 world_code text primary key, enabled boolean not null default true,
 online_interval_seconds integer not null default 300,
 offline_interval_seconds integer not null default 1200,
 offline_catchup_limit integer not null default 1,
 first_interval_seconds integer not null default 300,
 weights jsonb not null,
 updated_at timestamptz not null default now());
create table if not exists public.opportunity_v3_catalog(
 code text primary key, grade text not null check(grade in('黄品','玄品','地品','天品','仙品')),
 grade_sequence integer not null, title text not null, story text not null,
 positive_text text not null, negative_text text not null, is_active boolean not null default true,
 metadata jsonb not null default '{}'::jsonb, unique(grade,grade_sequence));
create table if not exists public.character_opportunity_v3_state(
 character_id uuid primary key references public.player_characters(id) on delete cascade,
 next_available_at timestamptz not null default (clock_timestamp()+interval '5 minutes'),
 last_seen_at timestamptz not null default clock_timestamp(), total_resolved bigint not null default 0,
 exclusive_pity jsonb not null default '{"late_bloomer":20,"lucky_encounter":20,"unyielding_heart":20,"sword_heart":20,"heaven_jealous":20}'::jsonb,
 acquired_exclusive_codes jsonb not null default '[]'::jsonb, last_result jsonb, updated_at timestamptz not null default now());
create table if not exists public.opportunity_v3_results(
 id uuid primary key default gen_random_uuid(), character_id uuid not null references public.player_characters(id) on delete cascade,
 catalog_code text references public.opportunity_v3_catalog(code), rarity text not null, path_key text not null check(path_key in('auspicious','risk')),
 reward_text text not null, penalty_text text, result_data jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists idx_opportunity_v3_results_character on public.opportunity_v3_results(character_id,created_at desc);
create table if not exists public.exclusive_technique_definitions(
 code text primary key,name text not null,fate_code text not null,fate_name text not null,cave_resource_code text not null,
 base_cultivation_multiplier numeric(8,4) not null default .30,max_level integer not null default 36,
 upgrade_cost_base integer not null default 1050,description text not null default '');
create table if not exists public.character_exclusive_techniques(
 id uuid primary key default gen_random_uuid(),character_id uuid not null references public.player_characters(id) on delete cascade,
 exclusive_code text not null references public.exclusive_technique_definitions(code),level integer not null default 1 check(level between 1 and 36),
 equipped boolean not null default false,acquired_at timestamptz not null default now(),unique(character_id,exclusive_code));
create unique index if not exists ux_character_exclusive_slot on public.character_exclusive_techniques(character_id) where equipped;
create table if not exists public.opportunity_v3_effect_ledger(
 id uuid primary key default gen_random_uuid(),character_id uuid not null references public.player_characters(id) on delete cascade,
 result_id uuid references public.opportunity_v3_results(id) on delete cascade,effect_type text not null,amount numeric not null default 0,
 starts_at timestamptz not null default now(),expires_at timestamptz,metadata jsonb not null default '{}',created_at timestamptz not null default now());
on conflict(code) do update set grade=excluded.grade,grade_sequence=excluded.grade_sequence,title=excluded.title,story=excluded.story,positive_text=excluded.positive_text,negative_text=excluded.negative_text,is_active=true;
on conflict(code) do update set name=excluded.name,fate_code=excluded.fate_code,fate_name=excluded.fate_name,cave_resource_code=excluded.cave_resource_code,base_cultivation_multiplier=.30,max_level=36,upgrade_cost_base=1050;
-- 11门普通功法：迁移补齐，一级基础效果保存在fixed_effects，V2展示/结算按1+0.1*(level-1)线性计算。
on conflict(code) do update set name=excluded.name,fixed_effects=excluded.fixed_effects,description=excluded.description;
create or replace function public.award_spirit_stones_v3(p_character_id uuid,p_amount bigint) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare iid uuid; begin if p_amount<=0 then return; end if; select id into iid from public.item_definitions where code='spirit_stone'; if iid is null then raise exception 'SPIRIT_STONE_ITEM_MISSING'; end if; insert into public.character_inventory(character_id,item_definition_id,quantity,is_bound,item_instance,acquired_year) values(p_character_id,iid,p_amount,false,'{}'::jsonb,1) on conflict(character_id,item_definition_id) do update set quantity=public.character_inventory.quantity+excluded.quantity,updated_at=now(); end$$;
create or replace function public.opportunity_v3_penalty_hours(p_grade text) returns integer language sql immutable as $$select case p_grade when '黄品' then 0 when '玄品' then 1 when '地品' then 6 when '天品' then 12 else 24 end$$;
create or replace function public.get_auto_opportunity_v3() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid(); c public.player_characters%rowtype; st public.character_opportunity_v3_state%rowtype; nowv timestamptz:=clock_timestamp(); due boolean; ev public.opportunity_v3_catalog%rowtype; roll numeric; rarity text; path text; res uuid; fatecode text; boost numeric:=1; nextv timestamptz;
begin
 if u is null then raise exception 'AUTH_REQUIRED'; end if;
 select * into c from public.player_characters where user_id=u and status in('active','secluded','missing') order by created_at desc limit 1;
 if c.id is null then raise exception 'CHARACTER_NOT_FOUND'; end if;
 select * into st from public.character_opportunity_v3_state where character_id=c.id for update;
 if exists(select 1 from public.character_fates cf join public.fates f on f.id=cf.fate_id where cf.character_id=c.id and cf.is_active and f.code='lucky_encounter') then boost:=1.10; end if;
 due:=nowv>=st.next_available_at;
 if due then
   roll:=random()*100;
   if roll<0.2*boost then rarity:='专属'; elsif roll<0.2*boost+0.5*boost then rarity:='仙品'; elsif roll<0.2*boost+0.5*boost+1.5*boost then rarity:='天品'; elsif roll<0.2*boost+0.5*boost+1.5*boost+8*boost then rarity:='地品'; elsif roll<35 then rarity:='玄品'; else rarity:='黄品'; end if;
   path:=case when (c.luck+c.mindset+random()*100)>=110 then 'auspicious' else 'risk' end;
   if rarity='专属' then
      select f.code into fatecode from public.character_fates cf join public.fates f on f.id=cf.fate_id where cf.character_id=c.id and cf.is_active order by cf.created_at limit 1;
      select ('专属功法·'||name)::text as title, ('天命牵引，一卷本命道法自虚空落下。')::text as story, ('获得专属功法《'||name||'》，一级修炼速度+30%；独立专属槽。')::text as positive_text, ('若命格不符，天道收回并补偿100灵石；本命权重永久累积。')::text as negative_text into ev.title,ev.story,ev.positive_text,ev.negative_text from public.exclusive_technique_definitions order by random() limit 1;
   else select * into ev from public.opportunity_v3_catalog where grade=rarity and is_active order by random() limit 1; end if;
   -- 基础可承载奖励：修为、灵石与临时/永久修炼效果写入现有系统；洞府原“灵石日产”统一映射至灵蕴/灵草/灵矿并记入账本。
   if ev.positive_text ~ '修为（([0-9]+)）' then update public.player_characters set cultivation=cultivation+((regexp_match(ev.positive_text,'修为（([0-9]+)）'))[1])::bigint where id=c.id; end if;
   if ev.positive_text ~ '灵石（([0-9]+)）' then perform public.award_spirit_stones_v3(c.id,((regexp_match(ev.positive_text,'灵石（([0-9]+)）'))[1])::bigint); end if;
   nextv:=nowv+interval '5 minutes'; update public.character_opportunity_v3_state set next_available_at=nextv,last_seen_at=nowv,total_resolved=total_resolved+1,last_result=jsonb_build_object('result_id',res,'title',ev.title,'content',ev.story,'reward_text',ev.positive_text,'penalty_text',ev.negative_text,'rarity',rarity,'rarity_name',rarity,'path_name',case path when 'auspicious' then '趋吉' else '涉险' end,'created_at',nowv),updated_at=nowv where character_id=c.id;
 else update public.character_opportunity_v3_state set last_seen_at=nowv,updated_at=nowv where character_id=c.id; end if;
 select * into st from public.character_opportunity_v3_state where character_id=c.id;
 return jsonb_build_object('status','waiting','automatic',true,'next_available_at',st.next_available_at,'seconds_until_next',greatest(0,extract(epoch from st.next_available_at-nowv)::int),'last_result',st.last_result,'online_interval_seconds',300,'offline_interval_seconds',1200,'offline_catchup_limit',1);
end$$;
create or replace function public.upgrade_exclusive_technique_v1(p_character_exclusive_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare u uuid:=auth.uid(); r record; cost bigint; begin select cet.*,pc.user_id into r from public.character_exclusive_techniques cet join public.player_characters pc on pc.id=cet.character_id where cet.id=p_character_exclusive_id and pc.user_id=u for update; if r.id is null then raise exception 'NOT_FOUND'; end if; if r.level>=36 then raise exception 'MAX_LEVEL'; end if; cost:=1050*r.level*r.level; select ci.quantity into r.spirit_stones from public.character_inventory ci join public.item_definitions i on i.id=ci.item_definition_id where ci.character_id=r.character_id and i.code='spirit_stone' for update; if coalesce(r.spirit_stones,0)<cost then raise exception 'INSUFFICIENT_SPIRIT_STONES'; end if; update public.character_inventory ci set quantity=quantity-cost,updated_at=now() from public.item_definitions i where ci.item_definition_id=i.id and ci.character_id=r.character_id and i.code='spirit_stone'; update public.character_exclusive_techniques set level=level+1 where id=r.id; return jsonb_build_object('success',true,'level',r.level+1,'cost',cost); end$$;
alter table public.opportunity_v3_settings enable row level security; alter table public.opportunity_v3_catalog enable row level security; alter table public.character_opportunity_v3_state enable row level security; alter table public.opportunity_v3_results enable row level security; alter table public.exclusive_technique_definitions enable row level security; alter table public.character_exclusive_techniques enable row level security; alter table public.opportunity_v3_effect_ledger enable row level security;
revoke all on function public.get_auto_opportunity_v3() from public,anon; grant execute on function public.get_auto_opportunity_v3() to authenticated;
revoke all on function public.upgrade_exclusive_technique_v1(uuid) from public,anon; grant execute on function public.upgrade_exclusive_technique_v1(uuid) to authenticated;
commit;
